public static int calculateTimeNeeded(int N) {
  if (N <= 0) {
    throw new IllegalArgumentException("N must be a positive integer.");
  }

  int timeNeeded = 0;

  for (int i = 0; i < N; i++) {
    int leftPerson = (i - 1 + N) % N;
    int rightPerson = (i + 1) % N;

    if (leftPerson == rightPerson) {
      // If the person is currently sitting on their own seat, they need to
      // move to the opposite end of the table
      timeNeeded++;
    } else {
      // If the person is currently sitting between two other people, they
      // need to move to the other side of the table
      timeNeeded += 2;
    }
  }

  return timeNeeded;
}

