public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Check if the starting n-tersection is invalid
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n) {
        return "cannot be travelled";
    }

    // Check if the ending n-tersection is invalid
    if (end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        return "cannot be travelled";
    }

    // Check if the starting n-tersection is the same as the ending n-tersection
    if (start[0] == end[0] && start[1] == end[1]) {
        return "can be travelled";
    }

    // Check if there is a path between the starting and ending n-tersections
    boolean[][] visited = new boolean[n][n];
    Queue<int[]> queue = new LinkedList<>();
    queue.add(start);
    visited[start[0]][start[1]] = true;

    while (!queue.isEmpty()) {
        int[] current = queue.remove();
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }

        for (int[] path : paths) {
            int newX = current[0] + path[0];
            int newY = current[1] + path[1];
            if (newX >= 0 && newX < n && newY >= 0 && newY < n && !visited[newX][newY]) {
                visited[newX][newY] = true;
                queue.add(new int[] {newX, newY});
            }
        }
    }

    return "cannot be travelled";
}

