        // Check if the current sum is divisible by k
        if (currentSum % k == 0) {
            pairCount++;
        }

        // Add the current element to the sum
        currentSum += arr[i];

        // Check if the number of pairs is equal to n/2
        if (pairCount == n / 2) {
            return true;
        }
    }

    // If we reach this point, it means that we did not find a pair that is divisible by k
    return false;
}

