        if (i == 0 || s.charAt(i) != s.charAt(i - 1)) {
            uniqueSubstrings.add(s.substring(startIndex, i));
            startIndex = i;
        }
    }

    // Add the last substring to the set
    uniqueSubstrings.add(s.substring(startIndex));

    // Return the size of the set, which is the maximum number of unique substrings
    return uniqueSubstrings.size();
}

